/**
 * Official sites for resources that interview reports recommend. Keys are matched against the
 * resource name with case, spaces and punctuation removed, so "Indiabix.com" and "IndiaBIX" both match.
 * URLs are curated here rather than generated by the model, so they never point somewhere invented.
 */
const OFFICIAL_SITES: readonly (readonly [key: string, url: string])[] = [
  ['geeksforgeeks', 'https://www.geeksforgeeks.org/'],
  ['leetcode', 'https://leetcode.com/'],
  ['indiabix', 'https://www.indiabix.com/'],
  ['w3schools', 'https://www.w3schools.com/'],
  ['hackerrank', 'https://www.hackerrank.com/'],
  ['hackerearth', 'https://www.hackerearth.com/'],
  ['nesoacademy', 'https://www.nesoacademy.org/'],
  ['javatpoint', 'https://www.javatpoint.com/'],
  ['interviewbit', 'https://www.interviewbit.com/'],
  ['careerride', 'https://www.careerride.com/'],
  ['tutorialspoint', 'https://www.tutorialspoint.com/'],
  ['prepinsta', 'https://prepinsta.com/'],
  ['takeuforward', 'https://takeuforward.org/'],
  ['takeyouforward', 'https://takeuforward.org/'],
  ['striver', 'https://takeuforward.org/'],
  ['nptel', 'https://nptel.ac.in/'],
  ['codechef', 'https://www.codechef.com/'],
  ['codeforces', 'https://codeforces.com/'],
  ['cses', 'https://cses.fi/problemset/'],
  ['kaggle', 'https://www.kaggle.com/'],
  ['analyticsvid', 'https://www.analyticsvidhya.com/'],
  ['towardsdatascience', 'https://towardsdatascience.com/'],
  ['statquest', 'https://statquest.org/'],
  ['3blue1brown', 'https://www.3blue1brown.com/'],
  ['brainstellar', 'https://brainstellar.com/'],
  ['sqlbolt', 'https://sqlbolt.com/'],
  ['freshersworld', 'https://www.freshersworld.com/'],
  ['codewithharry', 'https://www.codewithharry.com/'],
  ['wireshark', 'https://www.wireshark.org/'],
  ['glassdoor', 'https://www.glassdoor.co.in/'],
  ['ambitionbox', 'https://www.ambitionbox.com/'],
];

/** Teachers known mainly through their YouTube channels. */
const YOUTUBE_TEACHERS = ['telusko', 'kunalkushwaha', 'abdulbari', 'jennyslectures', 'allaboutelectronics', 'techdose'];

const normalise = (name: string) => name.toLowerCase().replace(/[^a-z0-9]/g, '');

/** Where a student can open a recommended resource: its official site, or a relevant search. */
export function resourceLink(name: string): string {
  const key = normalise(name);
  const site = OFFICIAL_SITES.find(([siteKey]) => key.includes(siteKey));
  if (site) return site[1];
  if (/youtube/i.test(name) || YOUTUBE_TEACHERS.some((teacher) => key.includes(teacher))) {
    return `https://www.youtube.com/results?search_query=${encodeURIComponent(name)}`;
  }
  return `https://www.google.com/search?q=${encodeURIComponent(`${name} placement preparation`)}`;
}
